BUILTINS = ("__LINE__", "__FILE__", "__COUNTER__")
VARIADIC_NAME = "__VA_ARGS__"
VARIADIC_ERROR = '"__VA_ARGS__" can only appear in the expansion of a variadic macro'


class DefinitionError(Exception):
    pass


class Macro:
    def __init__(self, name, parameters, variadic, replacement, position, main_file):
        self.name, self.parameters, self.variadic = name, parameters, variadic
        self.replacement, self.position, self.main_file = replacement, position, main_file
        self.expanded, self.tested = 0, 0

    def signature(self):
        if self.parameters is None:
            return self.name
        parameters = list(self.parameters)
        if self.variadic:
            parameters[-1] = "..."
        return self.name + "(" + ", ".join(parameters) + ")"

    def identical(self, other):
        return (self.parameters == other.parameters and self.variadic == other.variadic
                and [(token.spelling, token.space) for token in self.replacement]
                == [(token.spelling, token.space) for token in other.replacement])


def check_name(tokens, directive):
    if not tokens:
        return "no macro name given in #" + directive + " directive"
    if tokens[0].kind != "identifier":
        return "macro names must be identifiers"
    name = tokens[0].spelling
    if name == "defined":
        return '"defined" cannot be used as a macro name'
    if name in BUILTINS:
        operation = "redefine" if directive == "define" else "undefine"
        return f'cannot {operation} builtin macro "{name}"'
    return None


def parse(tokens, position, main_file):
    error = check_name(tokens, "define")
    if error is not None:
        raise DefinitionError(error)
    name = tokens[0].spelling
    if name == VARIADIC_NAME:
        raise DefinitionError(VARIADIC_ERROR)
    parameters, variadic, index = None, False, 1
    if len(tokens) > 1 and tokens[1].spelling == "(" and not tokens[1].space:
        parameters, index = [], 2
        if index == len(tokens):
            raise DefinitionError("missing ')' in macro parameter list")
        if tokens[index].spelling == ")":
            index += 1
        else:
            while True:
                if index == len(tokens):
                    raise DefinitionError("missing ')' in macro parameter list")
                token = tokens[index]
                if token.spelling == "...":
                    parameters.append(VARIADIC_NAME)
                    variadic = True
                elif token.kind == "identifier":
                    if token.spelling == VARIADIC_NAME:
                        raise DefinitionError(VARIADIC_ERROR)
                    if token.spelling in parameters:
                        raise DefinitionError(f'duplicate macro parameter "{token.spelling}"')
                    parameters.append(token.spelling)
                else:
                    raise DefinitionError(f'expected parameter name, found "{token.spelling}"')
                index += 1
                if index == len(tokens):
                    raise DefinitionError("missing ')' in macro parameter list")
                following = tokens[index].spelling
                index += 1
                if following == ")":
                    break
                if variadic:
                    raise DefinitionError(f'expected \')\' after "...", found "{following}"')
                if following != ",":
                    raise DefinitionError(f'expected \',\' or \')\', found "{following}"')
        parameters = tuple(parameters)
    replacement = list(tokens[index:])
    if replacement:
        replacement[0] = replacement[0]._replace(space=False)
        if replacement[0].spelling == "##" or replacement[-1].spelling == "##":
            raise DefinitionError("'##' cannot appear at either end of a macro expansion")
    for index, token in enumerate(replacement):
        if token.kind == "identifier" and token.spelling == VARIADIC_NAME and not variadic:
            raise DefinitionError(VARIADIC_ERROR)
        if token.spelling == "#" and parameters is not None:
            if index + 1 == len(replacement) or replacement[index + 1].kind != "identifier" or replacement[index + 1].spelling not in parameters:
                raise DefinitionError("'#' is not followed by a macro parameter")
    return Macro(name, parameters, variadic, tuple(replacement), position, main_file)

import sys
from collections import Counter, deque

from definitions import BUILTINS, VARIADIC_NAME
from lexer import Token, single_token


class Expander:
    def __init__(self, macros, diagnostic):
        self.macros, self.diagnostic = macros, diagnostic
        self.counter, self.depth = 0, 0
        self.builtin_counts = Counter()

    def error(self, context, token, message):
        self.diagnostic(context.position(token.line), "error", message)

    def builtin(self, token, context):
        self.builtin_counts[token.spelling] += 1
        if token.spelling == "__FILE__":
            kind, spelling = "string", '"' + context.display_file + '"'
        elif token.spelling == "__LINE__":
            kind, spelling = "number", str(context.position(token.line)[1])
        else:
            kind, spelling = "number", str(self.counter)
            self.counter += 1
        return Token(kind, spelling, token.line, token.space)

    def collect(self, pending, macro, token, context):
        arguments, separators, nesting = [[]], [], 0
        closing, consumed = None, None
        for index, current in enumerate(pending):
            if index == 0:
                continue
            if current.spelling == ")" and nesting == 0:
                closing, consumed = current, index + 1
                break
            if current.spelling == "," and nesting == 0:
                separators.append(current)
                arguments.append([])
            else:
                if current.spelling == "(":
                    nesting += 1
                elif current.spelling == ")":
                    nesting -= 1
                arguments[-1].append(current)
        if closing is None:
            self.error(context, token, f'unterminated argument list invoking macro "{macro.name}"')
            return None
        count = len(arguments)
        fixed = len(macro.parameters) - int(macro.variadic)
        error = None
        if (not macro.variadic and fixed == 0
                and (count != 1 or arguments[0])):
            error = f'macro "{macro.name}" passed {count} arguments, but takes just 0'
        elif count < fixed:
            error = f'macro "{macro.name}" requires {fixed} arguments, but only {count} given'
        elif count > fixed and not macro.variadic:
            error = f'macro "{macro.name}" passed {count} arguments, but takes just {fixed}'
        if error is not None:
            self.error(context, token, error)
            return None
        raw = dict(zip(macro.parameters[:fixed], arguments[:fixed]))
        if macro.variadic:
            variable = []
            for index in range(fixed, count):
                if index > fixed:
                    variable.append(separators[index - 1])
                variable.extend(arguments[index])
            raw[VARIADIC_NAME] = variable
        return raw, consumed, closing

    def stringize(self, tokens, sharp):
        pieces = []
        for index, token in enumerate(tokens):
            if index and token.space:
                pieces.append(" ")
            spelling = token.spelling
            if token.kind in ("string", "character"):
                spelling = spelling.replace("\\", "\\\\").replace('"', '\\"')
            pieces.append(spelling)
        return Token("string", '"' + "".join(pieces) + '"', sharp.line, sharp.space)

    def paste(self, left, right, token, context):
        if left.kind == "placemarker":
            return [right._replace(space=left.space)]
        if right.kind == "placemarker":
            return [left]
        spelling = left.spelling + right.spelling
        kind = single_token(spelling)
        if kind is not None:
            return [Token(kind, spelling, left.line, left.space, left.hide & right.hide)]
        self.error(context, token, f'pasting "{left.spelling}" and "{right.spelling}" does not give a valid preprocessing token')
        return [left, right._replace(space=False)]

    def substitute(self, macro, raw, token, hide, context):
        replacement, items, expanded = macro.replacement, [], {}
        index = 0
        while index < len(replacement):
            current = replacement[index]
            if current.spelling == "#" and macro.parameters is not None:
                parameter = replacement[index + 1].spelling
                items.append([self.stringize(raw[parameter], current)])
                index += 2
                continue
            if current.spelling == "##":
                items.append(current)
            elif current.kind == "identifier" and current.spelling in raw:
                adjacent = (index > 0 and replacement[index - 1].spelling == "##"
                            or index + 1 < len(replacement) and replacement[index + 1].spelling == "##")
                if adjacent:
                    sequence = raw[current.spelling]
                else:
                    if current.spelling not in expanded:
                        expanded[current.spelling] = self.expand(raw[current.spelling], context)
                    sequence = expanded[current.spelling]
                if sequence:
                    items.append([sequence[0]._replace(space=current.space), *sequence[1:]])
                else:
                    items.append([Token("placemarker", "", current.line, current.space)])
            else:
                items.append([current])
            index += 1
        pasted, index = [], 0
        while index < len(items):
            item = items[index]
            if isinstance(item, Token):
                left = pasted.pop()
                right = items[index + 1]
                if isinstance(right, Token):
                    right = [right]
                pasted.extend(self.paste(left, right[0], token, context))
                pasted.extend(right[1:])
                index += 2
            else:
                pasted.extend(item)
                index += 1
        result, carry_space = [], False
        for current in pasted:
            if current.kind == "placemarker":
                carry_space = carry_space or current.space
            else:
                result.append(current._replace(line=token.line, space=current.space or carry_space,
                                               hide=current.hide | hide))
                carry_space = False
        if result:
            result[0] = result[0]._replace(space=token.space)
        return result

    def expand(self, sequence, context):
        self.depth += 1
        sys.setrecursionlimit(max(sys.getrecursionlimit(), 8 * (self.depth + len(sequence) + 1) + 1000))
        try:
            pending, result = deque(sequence), []
            while pending:
                token = pending.popleft()
                if token.kind != "identifier" or token.spelling in token.hide:
                    result.append(token)
                    continue
                if token.spelling in BUILTINS:
                    result.append(self.builtin(token, context))
                    continue
                macro = self.macros.get(token.spelling)
                if macro is None or macro.parameters is not None and (not pending or pending[0].spelling != "("):
                    result.append(token)
                    continue
                raw = {}
                hide = token.hide | {macro.name}
                if macro.parameters is not None:
                    collected = self.collect(pending, macro, token, context)
                    if collected is None:
                        result.append(token)
                        continue
                    raw, consumed, closing = collected
                    for _ in range(consumed):
                        pending.popleft()
                    hide = (token.hide & closing.hide) | {macro.name}
                replacement = self.substitute(macro, raw, token, hide, context)
                macro.expanded += 1
                if not replacement and token.space and pending:
                    pending[0] = pending[0]._replace(space=True)
                pending.extendleft(reversed(replacement))
            return result
        finally:
            self.depth -= 1

import re
import sys


LEVELS = (("||",), ("&&",), ("|",), ("^",), ("&",), ("==", "!="),
          ("<", ">", "<=", ">="), ("<<", ">>"), ("+", "-"), ("*", "/", "%"))


class ExpressionError(Exception):
    pass


def integer_value(spelling):
    value = spelling
    for suffix in ("ll", "LL", "l", "L"):
        if value.endswith(suffix) and len(value) > len(suffix):
            value = value[:-len(suffix)]
            break
    if re.fullmatch(r"0[xX][0-9a-fA-F]+", value):
        return int(value, 16)
    if re.fullmatch(r"0[0-7]*", value):
        return int(value, 8)
    if re.fullmatch(r"[1-9][0-9]*", value):
        return int(value)
    raise ExpressionError(f'invalid integer constant "{spelling}"')


def character_value(spelling):
    value = spelling[1:-1]
    if len(value) == 1 and value not in "'\\":
        return ord(value)
    escapes = {"n": 10, "t": 9, "\\": 92, "'": 39, '"': 34, "0": 0}
    if len(value) == 2 and value[0] == "\\" and value[1] in escapes:
        return escapes[value[1]]
    raise ExpressionError("invalid character constant " + spelling)


class Parser:
    def __init__(self, tokens):
        self.tokens, self.position = tokens, 0

    def peek(self):
        return self.tokens[self.position].spelling if self.position < len(self.tokens) else None

    def expression(self):
        left = self.binary(0)
        if self.peek() == "?":
            self.position += 1
            first = self.expression()
            if self.peek() != ":":
                raise ExpressionError("'?' without following ':'")
            self.position += 1
            left = ("conditional", left, first, self.expression())
        return left

    def binary(self, level):
        if level == len(LEVELS):
            return self.unary()
        left = self.binary(level + 1)
        while self.peek() in LEVELS[level]:
            operator = self.peek()
            self.position += 1
            left = ("binary", operator, left, self.binary(level + 1))
        return left

    def unary(self):
        if self.peek() in ("+", "-", "!", "~"):
            operator = self.peek()
            self.position += 1
            return "unary", operator, self.unary()
        if self.position == len(self.tokens):
            raise ExpressionError("expected value at end of expression")
        token = self.tokens[self.position]
        self.position += 1
        if token.kind == "number":
            return "constant", integer_value(token.spelling)
        if token.kind == "character":
            return "constant", character_value(token.spelling)
        if token.kind == "identifier":
            return "identifier", token.spelling
        if token.spelling == "(":
            value = self.expression()
            if self.peek() != ")":
                raise ExpressionError("missing ')' in expression")
            self.position += 1
            return value
        raise ExpressionError(f'expected value before "{token.spelling}"')


def parse(tokens, directive):
    if not tokens:
        raise ExpressionError("#" + directive + " with no expression")
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 14 * len(tokens) + 1000))
    parser = Parser(tokens)
    tree = parser.expression()
    if parser.peek() is not None:
        raise ExpressionError(f'missing binary operator before "{parser.peek()}"')
    return tree


def binary_value(operator, first, second):
    if operator in ("/", "%"):
        if second == 0:
            raise ExpressionError("division by zero in #if")
        quotient = abs(first) // abs(second)
        if (first < 0) != (second < 0):
            quotient = -quotient
        return quotient if operator == "/" else first - second * quotient
    if operator == "+":
        return first + second
    if operator == "-":
        return first - second
    if operator == "*":
        return first * second
    if operator == "<<":
        return first << second
    if operator == ">>":
        return first >> second
    if operator == "&":
        return first & second
    if operator == "|":
        return first | second
    if operator == "^":
        return first ^ second
    comparisons = {"==": first == second, "!=": first != second, "<": first < second,
                   ">": first > second, "<=": first <= second, ">=": first >= second}
    return int(comparisons[operator])


def evaluate(tree, warning):
    pending, values = [("evaluate", tree)], []
    while pending:
        operation, item = pending.pop()
        if operation == "evaluate":
            kind = item[0]
            if kind == "constant":
                values.append(item[1])
            elif kind == "identifier":
                warning(f'identifier "{item[1]}" evaluates to 0')
                values.append(0)
            elif kind == "unary":
                pending.extend([("unary", item[1]), ("evaluate", item[2])])
            elif kind == "conditional":
                pending.extend([("choose", (item[2], item[3])), ("evaluate", item[1])])
            elif item[1] in ("&&", "||"):
                pending.extend([("logical", (item[1], item[3])), ("evaluate", item[2])])
            else:
                pending.extend([("binary", item[1]), ("evaluate", item[3]), ("evaluate", item[2])])
        elif operation == "choose":
            pending.append(("evaluate", item[0] if values.pop() != 0 else item[1]))
        elif operation == "logical":
            first = values.pop()
            if item[0] == "&&" and first == 0 or item[0] == "||" and first != 0:
                values.append(int(first != 0))
            else:
                pending.extend([("truth", None), ("evaluate", item[1])])
        elif operation == "truth":
            values.append(int(values.pop() != 0))
        elif operation == "unary":
            value = values.pop()
            values.append(value if item == "+" else -value if item == "-" else int(value == 0) if item == "!" else -value - 1)
        else:
            second, first = values.pop(), values.pop()
            values.append(binary_value(item, first, second))
    return values[0]

from pathlib import Path

from lexer import lex_source


STARTS = ("if", "ifdef", "ifndef")
BRANCHES = ("elif", "elifdef", "elifndef", "else")


def directive_name(tokens):
    if len(tokens) >= 2 and tokens[0].spelling == "#" and tokens[1].kind == "identifier":
        return tokens[1].spelling
    return None


def detect_guard(lines):
    nonempty = [line.tokens for line in lines if line.tokens]
    if not nonempty:
        return None
    first, last = nonempty[0], nonempty[-1]
    if len(first) != 3 or directive_name(first) != "ifndef" or first[2].kind != "identifier":
        return None
    if len(last) != 2 or directive_name(last) != "endif":
        return None
    depth = 0
    for index, tokens in enumerate(nonempty):
        name = directive_name(tokens)
        if name in BRANCHES and depth == 1:
            return None
        if name in STARTS:
            depth += 1
        elif name == "endif":
            depth -= 1
        if depth == 0 and index != len(nonempty) - 1:
            return None
    return first[2].spelling if depth == 0 else None


class SourceFile:
    def __init__(self, path, contents):
        self.path, self.physical_lines = path, contents.count("\n")
        self.lines = lex_source(contents)
        self.guard = detect_guard(self.lines)
        self.once = False
        self.entered, self.skipped, self.output_lines, self.skipped_lines = 0, 0, 0, 0


class IncludeManager:
    def __init__(self):
        self.files = {}

    def search(self, name, quoted):
        paths = [name, "include/" + name] if quoted else ["include/" + name]
        for path in paths:
            if Path("input", path).is_file():
                return path
        return None

    def load(self, path):
        if path not in self.files:
            contents = Path("input", path).read_bytes().decode("ascii")
            self.files[path] = SourceFile(path, contents)
        return self.files[path]

from collections import namedtuple


Token = namedtuple("Token", "kind spelling line space hide", defaults=[frozenset()])
LogicalLine = namedtuple("LogicalLine", "tokens start end")
PUNCTUATORS = (
    "...", "<<=", ">>=", "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||",
    "*=", "/=", "%=", "+=", "-=", "&=", "^=", "|=", "##", "[", "]", "(", ")", "{", "}",
    ".", "&", "*", "+", "-", "~", "!", "/", "%", "<", ">", "^", "|", "?", ":", ";", "=", ",", "#",
)


def identifier_start(character):
    return character == "_" or "a" <= character <= "z" or "A" <= character <= "Z"


def digit(character):
    return "0" <= character <= "9"


def read_token(text, position=0, header=False):
    character, length = text[position], len(text)
    if header and character == "<":
        closing, newline = text.find(">", position + 1), text.find("\n", position + 1)
        if closing >= 0 and (newline < 0 or closing < newline):
            return "header", text[position:closing + 1], closing + 1
    if identifier_start(character):
        end = position + 1
        while end < length and (identifier_start(text[end]) or digit(text[end])):
            end += 1
        return "identifier", text[position:end], end
    if digit(character) or character == "." and position + 1 < length and digit(text[position + 1]):
        end = position + 1
        while end < length:
            if text[end] in "eEpP" and end + 1 < length and text[end + 1] in "+-":
                end += 2
            elif identifier_start(text[end]) or digit(text[end]) or text[end] == ".":
                end += 1
            else:
                break
        return "number", text[position:end], end
    if character in "\"'":
        end = position + 1
        while end < length and text[end] != "\n":
            if text[end] == character:
                kind = "string" if character == '"' else "character"
                return kind, text[position:end + 1], end + 1
            if text[end] == "\\" and end + 1 < length and text[end + 1] != "\n":
                end += 2
            else:
                end += 1
    for punctuator in PUNCTUATORS:
        if text.startswith(punctuator, position):
            return "punctuator", punctuator, position + len(punctuator)
    return "other", character, position + 1


def splice(text):
    characters, positions = [], []
    index, line = 0, 1
    while index < len(text):
        if text.startswith("\\\n", index):
            index += 2
            line += 1
            continue
        character = text[index]
        characters.append(character)
        positions.append(line)
        if character == "\n":
            line += 1
        index += 1
    return "".join(characters), positions


def scan(text, positions, start=1):
    lines, tokens = [], []
    index, spaced = 0, True
    while index < len(text):
        if text[index] == " ":
            spaced = True
            index += 1
        elif text[index] == "\n":
            end = positions[index]
            lines.append(LogicalLine(tuple(tokens), start, end))
            tokens, start, spaced = [], end + 1, True
            index += 1
        elif text.startswith("/*", index):
            closing = text.find("*/", index + 2)
            index = len(text) if closing < 0 else closing + 2
            spaced = True
        elif text.startswith("//", index):
            closing = text.find("\n", index + 2)
            index = len(text) if closing < 0 else closing
            spaced = True
        else:
            header = len(tokens) == 2 and tokens[0].spelling == "#" and tokens[1].spelling == "include"
            kind, spelling, end = read_token(text, index, header)
            tokens.append(Token(kind, spelling, positions[index], spaced))
            index, spaced = end, False
    if tokens:
        lines.append(LogicalLine(tuple(tokens), start, positions[-1]))
    return tuple(lines)


def lex_source(text):
    spliced, positions = splice(text)
    return scan(spliced, positions)


def lex_definition(text, line):
    text += "\n"
    lines = scan(text, [line] * len(text), line)
    return tuple(token for logical in lines for token in logical.tokens)


def render(tokens):
    return "".join((" " if index and token.space else "") + token.spelling for index, token in enumerate(tokens))


def single_token(text):
    if not text or text.startswith(("//", "/*")):
        return None
    kind, _, end = read_token(text)
    return kind if end == len(text) else None

from collections import Counter, defaultdict, namedtuple
from itertools import groupby
from pathlib import Path
from types import SimpleNamespace

import definitions
import expression
from expander import Expander
from include_manager import BRANCHES, STARTS, IncludeManager, directive_name
from lexer import Token, lex_definition, read_token, render


CONDITIONALS = (*STARTS, *BRANCHES, "endif")
Header = namedtuple("Header", "rendering name quoted")


class DirectiveError(Exception):
    pass


class Inclusion:
    def __init__(self, source, depth):
        self.source, self.depth = source, depth
        self.display_file, self.offset = source.path, 0
        self.stack, self.segment = [], []

    def position(self, physical):
        return self.display_file, physical + self.offset

    def skipping(self):
        return bool(self.stack) and not self.stack[-1].active


def separator_needed(left, right):
    if left == "/" and right[0] in "/*":
        return True
    _, _, end = read_token(left + right)
    return end != len(left)


def output_render(tokens):
    pieces = []
    previous = None
    for token in tokens:
        if previous is not None and (token.space or separator_needed(previous, token.spelling)):
            pieces.append(" ")
        pieces.append(token.spelling)
        previous = token.spelling
    return "".join(pieces)


def following(heading, items):
    return heading + "".join(" " + item for item in items)


def header_specification(tokens, position=0):
    if position >= len(tokens):
        return None, position
    token = tokens[position]
    if token.kind in ("string", "header"):
        text = token.spelling
        return Header(text, text[1:-1], text.startswith('"')), position + 1
    if token.spelling == "<":
        closing = position + 1
        while closing < len(tokens) and tokens[closing].spelling != ">":
            closing += 1
        if closing == len(tokens):
            raise DirectiveError("missing terminating > character")
        text = "<" + render(tokens[position + 1:closing]) + ">"
        return Header(text, text[1:-1], False), closing + 1
    return None, position


def decimal_token(token):
    return token.kind == "number" and all("0" <= character <= "9" for character in token.spelling)


class Preprocessor:
    def __init__(self):
        self.macros, self.ever_defined = {}, set()
        self.saved = defaultdict(list)
        self.poisoned = set()
        self.manager = IncludeManager()
        self.expander = Expander(self.macros, self.diagnostic)
        self.output, self.history, self.diagnostics = [], [], []
        self.tree, self.conditional_records, self.regions = ["main.c"], [], []
        self.diagnostic_counts, self.condition_counts = Counter(), Counter()
        self.previous = None

    def diagnostic(self, position, kind, message):
        filename, line = position
        self.diagnostics.append(f"{filename}:{line}: {kind}: {message}")
        self.diagnostic_counts[kind] += 1

    def event(self, position, content):
        filename, line = position
        self.history.append(f"{filename}:{line}: {content}")

    def poison_check(self, context, tokens):
        for token in tokens:
            if token.kind == "identifier" and token.spelling in self.poisoned:
                self.diagnostic(context.position(token.line), "error", f'attempt to use poisoned "{token.spelling}"')

    def unused_check(self, macro):
        if macro.main_file and macro.expanded == 0 and macro.tested == 0:
            self.diagnostic(macro.position, "warning", f'macro "{macro.name}" is not used')

    def define(self, tokens, position, main_file):
        try:
            macro = definitions.parse(tokens, position, main_file)
        except definitions.DefinitionError as error:
            self.diagnostic(position, "error", str(error))
            return
        previous = self.macros.get(macro.name)
        if previous is None:
            self.macros[macro.name] = macro
            self.ever_defined.add(macro.name)
            operation = "define"
        elif previous.identical(macro):
            operation = "identical"
        else:
            self.unused_check(previous)
            filename, line = previous.position
            self.diagnostic(position, "warning", f'"{macro.name}" redefined (previous definition at {filename}:{line})')
            self.macros[macro.name] = macro
            self.ever_defined.add(macro.name)
            operation = "redefine"
        self.event(position, operation + " " + macro.signature())

    def undefine(self, tokens, position):
        error = definitions.check_name(tokens, "undef")
        if error is not None:
            self.diagnostic(position, "error", error)
            return
        if len(tokens) >= 2:
            self.diagnostic(position, "warning", "extra tokens at end of #undef directive")
        name = tokens[0].spelling
        if name in self.macros:
            self.unused_check(self.macros[name])
            del self.macros[name]
            self.event(position, "undef " + name)
        else:
            self.event(position, "undef " + name + " (not defined)")

    def process_defines(self):
        contents = Path("input/defines.txt").read_bytes().decode("ascii")
        for number, line in enumerate(contents.split("\n"), 1):
            if not line:
                continue
            if "=" in line:
                name, value = line.split("=", 1)
                text = name + " " + value
            else:
                text = line + " 1"
            self.define(lex_definition(text, number), ("defines.txt", number), False)

    def marker(self, filename, line, flag=None):
        text = f'# {line} "{filename}"'
        if flag is not None:
            text += " " + str(flag)
        self.output.append(text)
        self.previous = filename, line - 1

    def output_line(self, context, physical, text):
        filename, line = context.position(physical)
        previous_file, previous_line = self.previous
        if filename == previous_file and previous_line < line <= previous_line + 8:
            self.output.extend([""] * (line - previous_line - 1))
        else:
            self.marker(filename, line)
        self.output.append(text)
        self.previous = filename, line
        context.source.output_lines += 1

    def flush(self, context):
        segment, context.segment = context.segment, []
        if not segment:
            return
        self.poison_check(context, segment)
        expanded = self.expander.expand(segment, context)
        for physical, group in groupby(expanded, key=lambda token: token.line):
            self.output_line(context, physical, output_render(list(group)))

    def macro_defined(self, name):
        if name in self.macros:
            self.macros[name].tested += 1
            return True
        return name in definitions.BUILTINS or name == "__has_include"

    def replace_operators(self, context, operands):
        replaced, position = [], 0
        while position < len(operands):
            token = operands[position]
            if token.kind == "identifier" and token.spelling == "defined":
                index = position + 1
                parenthesized = index < len(operands) and operands[index].spelling == "("
                if parenthesized:
                    index += 1
                if index == len(operands) or operands[index].kind != "identifier":
                    raise DirectiveError('operator "defined" requires an identifier')
                name = operands[index].spelling
                index += 1
                if parenthesized:
                    if index == len(operands) or operands[index].spelling != ")":
                        raise DirectiveError('missing \')\' after "defined"')
                    index += 1
                value = self.macro_defined(name)
            elif token.kind == "identifier" and token.spelling == "__has_include":
                index = position + 1
                if index == len(operands) or operands[index].spelling != "(":
                    raise DirectiveError('missing \'(\' after "__has_include"')
                header, index = header_specification(operands, index + 1)
                if header is None or not header.name:
                    raise DirectiveError('operator "__has_include" requires a header-name')
                if index == len(operands) or operands[index].spelling != ")":
                    raise DirectiveError('missing \')\' after "__has_include" operand')
                index += 1
                value = self.manager.search(header.name, header.quoted) is not None
            else:
                replaced.append(token)
                position += 1
                continue
            replaced.append(Token("number", str(int(value)), token.line, token.space))
            position = index
        return replaced

    def test(self, context, logical, name, operands):
        position = context.position(logical.tokens[0].line)
        self.poison_check(context, operands)
        if name not in ("if", "elif"):
            if not operands:
                self.diagnostic(position, "error", "no macro name given in #" + name + " directive")
                return None, None
            if operands[0].kind != "identifier":
                self.diagnostic(position, "error", "macro names must be identifiers")
                return None, None
            if len(operands) >= 2:
                self.diagnostic(position, "warning", "extra tokens at end of #" + name + " directive")
            defined = self.macro_defined(operands[0].spelling)
            value = not defined if name in ("ifndef", "elifndef") else defined
            return int(value), None
        try:
            replaced = self.replace_operators(context, operands)
        except DirectiveError as error:
            self.diagnostic(position, "error", str(error))
            return None, None
        expanded = self.expander.expand(replaced, context)
        try:
            tree = expression.parse(expanded, name)
            value = expression.evaluate(tree, lambda message: self.diagnostic(position, "warning", message))
        except expression.ExpressionError as error:
            self.diagnostic(position, "error", str(error))
            return None, expanded
        return value, expanded

    def test_description(self, name, value, expanded):
        if value is None:
            description = "not taken (error)"
        else:
            description = "taken" if value != 0 else "not taken"
            if name in ("if", "elif"):
                description += f" (value {value})"
        if expanded is not None:
            description += " [" + output_render(expanded) + "]"
        return description

    def close_region(self, context, block, end):
        start = block.skip_start
        if start is not None and end >= start:
            filename, first = context.position(start)
            last = context.position(end)[1]
            self.regions.append(f"{filename}:{first}-{last} lines={end - start + 1}")
            context.source.skipped_lines += end - start + 1
        block.skip_start = None

    def conditional_record(self, position, depth, name, operands, description):
        filename, line = position
        directive = "#" + name
        if operands:
            directive += " " + render(operands)
        self.conditional_records.append(f"{filename}:{line}: " + "  " * depth + directive + " => " + description)
        for prefix, category in (("taken", "taken"), ("not taken", "not_taken"), ("skipped", "skipped"),
                                 ("not evaluated", "not_evaluated"), ("closes", "endif")):
            if description.startswith(prefix):
                self.condition_counts[category] += 1
                break

    def conditional(self, context, logical, name, operands):
        position = context.position(logical.tokens[0].line)
        if name in STARTS:
            parent = not context.stack or context.stack[-1].active
            block = SimpleNamespace(kind=name, position=position, parent=parent, chosen=False,
                                    active=False, else_seen=False, skip_start=None)
            if parent:
                value, expanded = self.test(context, logical, name, operands)
                if value is not None and value != 0:
                    block.chosen, block.active = True, True
                else:
                    block.skip_start = logical.end + 1
                description = self.test_description(name, value, expanded)
            else:
                description = "skipped"
            self.conditional_record(position, len(context.stack), name, operands, description)
            context.stack.append(block)
            return
        if not context.stack:
            self.diagnostic(position, "error", "#" + name + " without #if")
            return
        block, depth = context.stack[-1], len(context.stack) - 1
        self.close_region(context, block, logical.start - 1)
        if name == "endif":
            context.stack.pop()
            if block.parent and operands:
                self.diagnostic(position, "warning", "extra tokens at end of #endif directive")
            description = f"closes #{block.kind} at line {block.position[1]}"
        else:
            if block.else_seen:
                self.diagnostic(position, "error", "#" + name + " after #else")
            if name == "else":
                if block.parent and operands:
                    self.diagnostic(position, "warning", "extra tokens at end of #else directive")
                block.else_seen = True
                if block.parent:
                    block.active = not block.chosen
                    block.chosen = True
                    description = "taken" if block.active else "not taken"
                else:
                    block.active, description = False, "skipped"
            elif not block.parent:
                block.active, description = False, "skipped"
            elif block.chosen:
                block.active, description = False, "not evaluated"
            else:
                value, expanded = self.test(context, logical, name, operands)
                block.active = value is not None and value != 0
                if block.active:
                    block.chosen = True
                description = self.test_description(name, value, expanded)
            if block.parent and not block.active:
                block.skip_start = logical.end + 1
        self.conditional_record(position, depth, name, operands, description)

    def include(self, context, logical, operands):
        position = context.position(logical.tokens[0].line)
        try:
            sequence = operands
            header, consumed = header_specification(sequence)
            if header is None and sequence:
                sequence = self.expander.expand(sequence, context)
                header, consumed = header_specification(sequence)
            if header is None:
                raise DirectiveError('#include expects "FILENAME" or <FILENAME>')
            if consumed < len(sequence):
                self.diagnostic(position, "warning", "extra tokens at end of #include directive")
            if not header.name:
                raise DirectiveError("empty filename in #include")
        except DirectiveError as error:
            self.diagnostic(position, "error", str(error))
            return
        prefix = "  " * (context.depth + 1) + str(logical.tokens[0].line) + ": "
        path = self.manager.search(header.name, header.quoted)
        if path is None:
            self.tree.append(prefix + header.rendering + " [not found]")
            self.diagnostic(position, "error", "cannot find include file " + header.rendering)
            return
        previous = self.manager.files.get(path)
        if previous is not None and previous.once:
            self.tree.append(prefix + path + " [skipped: pragma once]")
            previous.skipped += 1
            return
        if previous is not None and previous.guard is not None and previous.guard in self.macros:
            self.tree.append(prefix + path + " [skipped: guard " + previous.guard + "]")
            previous.skipped += 1
            return
        if context.depth + 1 > 8:
            self.tree.append(prefix + path + " [too deep]")
            self.diagnostic(position, "error", "#include nested too deeply")
            return
        self.tree.append(prefix + path)
        self.marker(path, 1, 1)
        self.process_file(path, context.depth + 1)
        filename, line = context.position(logical.end + 1)
        self.marker(filename, line, 2)

    def line_directive(self, context, logical, operands):
        position = context.position(logical.tokens[0].line)
        if not operands or not decimal_token(operands[0]):
            operands = self.expander.expand(operands, context)
        if len(operands) not in (1, 2) or not decimal_token(operands[0]) or len(operands) == 2 and operands[1].kind != "string":
            self.diagnostic(position, "error", "invalid #line directive")
            return
        line = int(operands[0].spelling)
        if not 1 <= line <= 2147483647:
            self.diagnostic(position, "error", "line number out of range")
            return
        context.offset = line - (logical.end + 1)
        if len(operands) == 2:
            context.display_file = operands[1].spelling[1:-1]

    def macro_pragma(self, position, operands, operation):
        if len(operands) != 4 or operands[1].spelling != "(" or operands[2].kind != "string" or operands[3].spelling != ")":
            self.diagnostic(position, "error", "invalid #pragma " + operation + " directive")
            return
        name = operands[2].spelling[1:-1]
        if operation == "push_macro":
            self.saved[name].append(self.macros.get(name))
            self.event(position, "push " + name)
        elif not self.saved[name]:
            self.diagnostic(position, "warning", f'no matching push_macro for "{name}"')
        else:
            macro = self.saved[name].pop()
            if macro is None:
                self.macros.pop(name, None)
                self.event(position, "pop " + name + " (undefined)")
            else:
                self.macros[name] = macro
                self.event(position, "pop " + name)

    def pragma(self, context, logical, operands):
        position = context.position(logical.tokens[0].line)
        name = operands[0].spelling if operands and operands[0].kind == "identifier" else None
        if name == "once":
            if len(operands) >= 2:
                self.diagnostic(position, "warning", "extra tokens at end of #pragma once directive")
            if context.depth == 0:
                self.diagnostic(position, "warning", "#pragma once in main file")
            context.source.once = True
        elif len(operands) >= 2 and operands[0].spelling == "GCC" and operands[1].spelling == "poison":
            if any(token.kind != "identifier" for token in operands[2:]):
                self.diagnostic(position, "error", "invalid #pragma GCC poison directive")
                return
            for token in operands[2:]:
                if token.spelling in self.macros:
                    self.diagnostic(position, "warning", f'poisoning existing macro "{token.spelling}"')
                self.poisoned.add(token.spelling)
        elif name in ("push_macro", "pop_macro"):
            self.macro_pragma(position, operands, name)
        else:
            text = "#pragma" + (" " + render(operands) if operands else "")
            self.output_line(context, logical.tokens[0].line, text)

    def directive(self, context, logical, name, operands):
        if len(logical.tokens) == 1:
            return
        poisoning = name == "pragma" and len(operands) >= 2 and operands[0].spelling == "GCC" and operands[1].spelling == "poison"
        if not poisoning:
            self.poison_check(context, operands)
        position = context.position(logical.tokens[0].line)
        if name == "define":
            self.define(operands, position, context.depth == 0)
        elif name == "undef":
            self.undefine(operands, position)
        elif name == "include":
            self.include(context, logical, operands)
        elif name == "line":
            self.line_directive(context, logical, operands)
        elif name in ("error", "warning"):
            text = "#" + name + (" " + render(operands) if operands else "")
            self.diagnostic(position, name, text)
        elif name == "pragma":
            self.pragma(context, logical, operands)
        else:
            self.diagnostic(position, "error", "invalid preprocessing directive #" + logical.tokens[1].spelling)

    def process_file(self, path, depth):
        source = self.manager.load(path)
        source.entered += 1
        context = Inclusion(source, depth)
        for logical in source.lines:
            tokens = logical.tokens
            is_directive = bool(tokens) and tokens[0].spelling == "#"
            name = directive_name(tokens)
            operands = tokens[2:]
            if is_directive and name in CONDITIONALS:
                self.flush(context)
                self.conditional(context, logical, name, operands)
            elif context.skipping():
                continue
            elif is_directive:
                self.flush(context)
                self.directive(context, logical, name, operands)
            else:
                context.segment.extend(tokens)
        self.flush(context)
        for block in context.stack:
            self.close_region(context, block, source.physical_lines)
        for block in context.stack:
            self.diagnostic(block.position, "error", "unterminated #" + block.kind)

    def include_report(self):
        lines = self.tree + ["", "== files =="]
        for path in sorted(self.manager.files):
            source = self.manager.files[path]
            guard = source.guard if source.guard is not None else "-"
            once = "yes" if source.once else "no"
            lines.append(f"{path} entered={source.entered} skipped={source.skipped} lines={source.physical_lines} "
                         f"output_lines={source.output_lines} skipped_lines={source.skipped_lines} guard={guard} once={once}")
        lines.append("")
        current, has_path = "main.o:", False
        for path in self.manager.files:
            if len(current) + 1 + len(path) > 76 and has_path:
                lines.append(current + " \\")
                current, has_path = " ", False
            current += " " + path
            has_path = True
        lines.append(current)
        return lines

    def references(self):
        references = {}
        for name, macro in self.macros.items():
            parameters = set(macro.parameters or ())
            references[name] = sorted({token.spelling for token in macro.replacement
                                       if token.kind == "identifier" and token.spelling in self.macros
                                       and token.spelling not in parameters})
        return references

    def recursive(self, name, references):
        pending, seen = list(references[name]), set()
        while pending:
            current = pending.pop()
            if current == name:
                return True
            if current not in seen:
                seen.add(current)
                pending.extend(references[current])
        return False

    def macro_report(self):
        lines = ["== history ==", *self.history, "", "== table =="]
        references = self.references()
        for name in sorted(self.macros):
            macro = self.macros[name]
            definition = "#define " + macro.signature()
            if macro.replacement:
                definition += " " + render(macro.replacement)
            lines.append(definition)
            filename, line = macro.position
            recursive = "yes" if self.recursive(name, references) else "no"
            lines.append(f"  at {filename}:{line} expanded={macro.expanded} tested={macro.tested} recursive={recursive}")
            lines.append(following("  refs:", references[name]))
        object_like = sum(macro.parameters is None for macro in self.macros.values())
        lines.extend(["", f"macros={len(self.macros)} object_like={object_like} function_like={len(self.macros) - object_like}"])
        lines.append(following("undefined:", sorted(self.ever_defined - self.macros.keys())))
        counts = self.expander.builtin_counts
        lines.append(f"builtins: __COUNTER__={counts['__COUNTER__']} __FILE__={counts['__FILE__']} __LINE__={counts['__LINE__']}")
        return lines

    def conditional_report(self):
        lines = self.conditional_records + ["", "== skipped regions ==", *self.regions, ""]
        counts = self.condition_counts
        lines.append(f"directives={len(self.conditional_records)} taken={counts['taken']} not_taken={counts['not_taken']} "
                     f"skipped={counts['skipped']} not_evaluated={counts['not_evaluated']} endif={counts['endif']} regions={len(self.regions)}")
        return lines

    def write_reports(self):
        diagnostic_lines = self.diagnostics + [f"errors={self.diagnostic_counts['error']} warnings={self.diagnostic_counts['warning']}"]
        reports = (("preprocessed.txt", self.output), ("includes.txt", self.include_report()),
                   ("macros.txt", self.macro_report()), ("conditionals.txt", self.conditional_report()),
                   ("diagnostics.txt", diagnostic_lines))
        output = Path("output")
        output.mkdir(exist_ok=True)
        for name, lines in reports:
            text = "\n".join(line.rstrip(" ") for line in lines) + "\n"
            (output / name).write_text(text, encoding="ascii", newline="\n")

    def run(self):
        self.process_defines()
        self.marker("main.c", 1)
        self.process_file("main.c", 0)
        for name in sorted(self.macros):
            self.unused_check(self.macros[name])
        self.write_reports()


def main():
    Preprocessor().run()


if __name__ == "__main__":
    main()
